command:
import json,pathlib,subprocess,sys
helper,reference,candidate,output=sys.argv[1:]
summary={}
for degree in (3,12):
 report=str(pathlib.Path(output)/('l'+str(degree)+'-checks.json'))
 command=[sys.executable,helper,'--reference-root',reference,'--reference-job','reference-l'+str(degree),'--candidate-root',candidate,'--candidate-job','global-generated-w1-l'+str(degree),'--output',report]
 run=subprocess.run(command,check=False)
 summary[str(degree)]={'returncode':run.returncode,'report':pathlib.Path(report).name}
with (pathlib.Path(output)/'controls-summary.json').open('x') as stream:json.dump(summary,stream,indent=2)
sys.exit(0 if all(x['returncode']==0 for x in summary.values()) else 1)
